<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import InvitationPreviewRenderer from '@/Components/InvitationPreviewRenderer.vue';
import PageHeader from '@/Components/UI/PageHeader.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';

const props = defineProps<{ event:any; step:number; templates:any[]; overrides:any; resolvedSettings:any; previewInvitation:any; workflow:any; timezones:string[] }>();
const dateValue = (value:any) => value ? value.slice(0, 10) : '';
const timeValue = (value:any) => value ? value.slice(0, 5) : '';
const previewing = ref<any | null>(null);
const design = useForm({ template_id: props.event.template_id || '', settings: { palette_key: props.overrides.palette_key || '', font_pair_key: props.overrides.font_pair_key || '' } });
const information = useForm({ event_type: props.event.event_type || '', title: props.event.title || '', host_name: props.event.host_name || '', second_host_name: props.event.second_host_name || '', description: props.event.description || '', main_date: dateValue(props.event.main_date), start_time: timeValue(props.event.start_time), end_time: timeValue(props.event.end_time), event_timezone: props.event.event_timezone || '', venue: props.event.venue || '', address: props.event.address || '', location_url: props.event.location_url || '', rsvp_deadline: dateValue(props.event.rsvp_deadline) });
const selectedTemplate = computed(() => props.templates.find((template:any) => template.id === Number(design.template_id)) || null);
const paletteOptions = computed(() => selectedTemplate.value?.palettes || []);
const fontPairOptions = computed(() => selectedTemplate.value?.font_pairs || []);
const previewInvitation = computed(() => ({ ...props.previewInvitation, template: selectedTemplate.value ? { name: selectedTemplate.value.name, component_key: selectedTemplate.value.component_key } : props.previewInvitation.template, settings: { ...props.resolvedSettings, ...(paletteOptions.value.find((option:any) => option.key === (design.settings.palette_key || selectedTemplate.value?.default_palette_key)) || {}), ...(fontPairOptions.value.find((option:any) => option.key === (design.settings.font_pair_key || selectedTemplate.value?.default_font_pair_key)) || {}) } }));
const previewFor = computed(() => previewing.value ? { ...previewInvitation.value, template: { name: previewing.value.name, component_key: previewing.value.component_key }, settings: { ...props.resolvedSettings, ...previewing.value.palettes.find((option:any) => option.key === previewing.value.default_palette_key), ...previewing.value.font_pairs.find((option:any) => option.key === previewing.value.default_font_pair_key) } } : previewInvitation.value);
const completion = computed(() => [information.event_type, information.title, information.host_name, information.main_date, information.start_time, information.event_timezone].filter(Boolean).length);
const nextDay = computed(() => Boolean(information.start_time && information.end_time && information.end_time < information.start_time));
const saveDesign = () => design.transform((data:any) => ({ template_id: data.template_id, settings: { palette_key: data.settings.palette_key || null, font_pair_key: data.settings.font_pair_key || null } })).patch(route('events.setup.save', { event: props.event.id, step: 'design' }));
const saveInformation = () => information.patch(route('events.setup.save', { event: props.event.id, step: 'information' }));
const backToDesign = () => router.get(route('events.setup', { event: props.event.id, step: 1 }));
watch(() => design.template_id, (current, previous) => { if (previous !== undefined && current !== previous) { design.settings.palette_key = ''; design.settings.font_pair_key = ''; } });
</script>

<template>
    <Head title="Create Your Invitation" />
    <AuthenticatedLayout>
        <template #header><PageHeader :title="step === 1 ? 'Choose Your Invitation Design' : 'Enter Your Information'" :eyebrow="step === 1 ? 'Step 1 of 3' : 'Step 2 of 3'" :subtitle="step === 1 ? 'Start with the invitation experience your guests will receive.' : 'Add the essential information before the final personalization step.'"><template #actions><Link :href="route('events.show', event.id)" class="fe-btn fe-btn-secondary">Exit</Link></template></PageHeader></template>
        <main class="fe-page fe-page-wide space-y-6">
            <ol class="grid gap-2 sm:grid-cols-3" aria-label="Invitation creation progress"><li class="rounded-xl border p-3" :class="step === 1 ? 'border-[color:var(--fe-primary)] bg-[color:var(--fe-surface-elevated)]' : 'border-[color:var(--fe-border)]'"><span class="text-xs font-bold uppercase tracking-[.15em]">1 · Design</span><p class="mt-1 text-sm">Choose a template</p></li><li class="rounded-xl border p-3" :class="step === 2 ? 'border-[color:var(--fe-primary)] bg-[color:var(--fe-surface-elevated)]' : 'border-[color:var(--fe-border)]'"><span class="text-xs font-bold uppercase tracking-[.15em]">2 · Information</span><p class="mt-1 text-sm">Add essential details</p></li><li class="rounded-xl border p-3 border-[color:var(--fe-border)]"><span class="text-xs font-bold uppercase tracking-[.15em]">3 · Personalize</span><p class="mt-1 text-sm">Finish your invitation</p></li></ol>

            <form v-if="step === 1" class="space-y-6" @submit.prevent="saveDesign"><section class="rounded-3xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-5 shadow-sm sm:p-8"><div class="max-w-2xl"><p class="fe-page-eyebrow">Your invitation style</p><h2 class="fe-section-title mt-1">Choose your invitation experience.</h2><p class="fe-section-copy mt-3">Choose the style for your celebration. You can personalize the wording, colors, and details in the next steps.</p></div><div class="mt-7 grid gap-5 lg:grid-cols-3"><article v-for="(template, index) in templates" :key="template.id" class="overflow-hidden rounded-2xl border p-3 transition" :class="Number(design.template_id) === template.id ? 'border-[color:var(--fe-primary)] ring-2 ring-[color:var(--fe-primary)]/20' : 'border-[color:var(--fe-border)]'"><button type="button" class="template-phone w-full text-left" :class="`template-phone--${template.component_key}`" @click="design.template_id = template.id"><span class="template-phone__speaker"></span><span class="template-phone__screen"><span class="template-phone__eyebrow">FormalEvites</span><strong>{{ event.host_name || 'Your celebration' }}</strong><em>{{ template.component_key === 'romantic-floral' ? 'A floral celebration' : template.component_key === 'editorial-luxury' ? 'A refined reveal' : 'A wedding day story' }}</em><small>{{ dateValue(event.main_date) || 'Your date' }}</small></span></button><div class="mt-4"><p class="fe-page-eyebrow">Template {{ index + 1 }}</p><h3 class="mt-1 font-semibold">{{ template.name }}</h3><p class="mt-1 min-h-10 text-sm text-[color:var(--fe-text-secondary)]">{{ template.description }}</p><div class="mt-4 flex gap-3"><button type="button" class="text-sm font-semibold text-[color:var(--fe-primary)] underline" @click="previewing = template">Preview</button><button type="button" class="text-sm font-semibold text-[color:var(--fe-primary)] underline" @click="design.template_id = template.id">Customize template</button></div></div></article></div><InputError :message="design.errors.template_id" class="mt-3" /><div v-if="selectedTemplate && (paletteOptions.length || fontPairOptions.length)" class="mt-7 grid max-w-2xl gap-4 border-t border-[color:var(--fe-border)] pt-6 sm:grid-cols-2"><label v-if="paletteOptions.length">Color style<select v-model="design.settings.palette_key" class="mt-1 w-full"><option value="">Template default</option><option v-for="option in paletteOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></label><label v-if="fontPairOptions.length">Typography<select v-model="design.settings.font_pair_key" class="mt-1 w-full"><option value="">Template default</option><option v-for="option in fontPairOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></label></div><div class="mt-7 flex justify-end"><button :disabled="!design.template_id || design.processing || !workflow.can_manage" class="fe-btn fe-btn-primary">{{ design.processing ? 'Saving...' : 'Continue to your information' }}</button></div></section></form>

            <form v-else class="mx-auto max-w-3xl rounded-3xl border border-[color:var(--fe-border)] bg-[color:var(--fe-surface)] p-5 shadow-sm sm:p-8" @submit.prevent="saveInformation"><fieldset :disabled="!workflow.can_manage" class="space-y-6"><div class="flex flex-wrap items-end justify-between gap-4"><div><p class="fe-page-eyebrow">Essential invitation details</p><h2 class="fe-section-title mt-1">Give guests the information they need.</h2></div><p class="rounded-full bg-[color:var(--fe-surface-elevated)] px-3 py-1 text-sm font-semibold">{{ completion }} of 6 essentials ready</p></div><div class="grid gap-4 sm:grid-cols-2"><label>Event type<select v-model="information.event_type" class="mt-1 w-full"><option value="">Select type</option><option v-for="type in ['wedding','engagement','bridal_shower','birthday','graduation','baptism','communion']" :key="type" :value="type">{{ type.replaceAll('_', ' ') }}</option></select><InputError :message="information.errors.event_type" /></label><label>Invitation title<input v-model="information.title" class="mt-1 w-full" /><InputError :message="information.errors.title" /></label><label>First host<input v-model="information.host_name" class="mt-1 w-full" /><InputError :message="information.errors.host_name" /></label><label>Second host <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.second_host_name" class="mt-1 w-full" /></label><label>Event date<input v-model="information.main_date" type="date" class="mt-1 w-full" /><InputError :message="information.errors.main_date" /></label><label>RSVP deadline <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.rsvp_deadline" type="date" class="mt-1 w-full" /><InputError :message="information.errors.rsvp_deadline" /></label><label>Start time<input v-model="information.start_time" type="time" class="mt-1 w-full" /><InputError :message="information.errors.start_time" /></label><label>End time <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.end_time" type="time" class="mt-1 w-full" /><p v-if="nextDay" class="mt-1 text-xs font-medium text-[color:var(--fe-accent)]">Ends the next day</p><InputError :message="information.errors.end_time" /></label><label class="sm:col-span-2">Timezone<select v-model="information.event_timezone" class="mt-1 w-full"><option value="">Select timezone</option><option v-for="timezone in timezones" :key="timezone" :value="timezone">{{ timezone }}</option></select><InputError :message="information.errors.event_timezone" /></label><label>Venue <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.venue" class="mt-1 w-full" /></label><label>Address <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.address" class="mt-1 w-full" /></label><label class="sm:col-span-2">Location URL <span class="text-[color:var(--fe-text-muted)]">(optional)</span><input v-model="information.location_url" type="url" class="mt-1 w-full" /><InputError :message="information.errors.location_url" /></label><label class="sm:col-span-2">Invitation wording <span class="text-[color:var(--fe-text-muted)]">(optional)</span><textarea v-model="information.description" rows="4" class="mt-1 w-full" /></label></div><div class="flex flex-wrap items-center justify-between gap-3 border-t border-[color:var(--fe-border)] pt-6"><button type="button" class="fe-btn fe-btn-secondary" @click="backToDesign">Previous</button><button :disabled="information.processing" class="fe-btn fe-btn-primary">{{ information.processing ? 'Saving...' : 'Continue to personalize' }}</button></div></fieldset></form>
        </main>
        <div v-if="previewing" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4" role="dialog" aria-modal="true" aria-label="Template preview"><div class="max-h-[92dvh] w-full max-w-xl overflow-auto rounded-3xl bg-white p-4 shadow-2xl"><div class="mb-3 flex items-center justify-between"><p class="font-semibold">{{ previewing.name }} preview</p><button type="button" class="fe-btn fe-btn-secondary" @click="previewing = null">Close</button></div><iframe v-if="previewing.demo_url" :src="previewing.demo_url" :title="`${previewing.name} demo`" class="h-[75dvh] w-full border-0" /><InvitationPreviewRenderer v-else :invitation="previewFor" /></div></div>
    </AuthenticatedLayout>
</template>

<style scoped>
.template-phone { position: relative; display: block; aspect-ratio: 9 / 15; margin: 0 auto; max-width: 13.5rem; padding: .5rem; border: .35rem solid #141414; border-radius: 1.65rem; background: #141414; box-shadow: 0 1.2rem 2.5rem rgb(15 23 42 / .18); }
.template-phone__speaker { display: block; position: absolute; z-index: 1; top: .72rem; left: 50%; width: 3.2rem; height: .25rem; transform: translateX(-50%); border-radius: 999px; background: rgb(255 255 255 / .55); }
.template-phone__screen { display: flex; height: 100%; padding: 2.4rem 1rem 1rem; border-radius: 1.2rem; flex-direction: column; justify-content: flex-end; color: white; text-align: center; }
.template-phone__eyebrow { margin-bottom: auto; font-size: .55rem; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; opacity: .75; }
.template-phone strong { font-family: Georgia, serif; font-size: 1.55rem; font-weight: 400; line-height: .95; }
.template-phone em { margin-top: .85rem; font-family: Georgia, serif; font-size: .85rem; }
.template-phone small { margin-top: 2.2rem; font-size: .65rem; letter-spacing: .1em; text-transform: uppercase; }
.template-phone--romantic-floral .template-phone__screen { background: radial-gradient(circle at 20% 10%, #fbe4e2, transparent 30%), linear-gradient(160deg, #fffaf5, #b46c78); color: #542033; }
.template-phone--editorial-luxury .template-phone__screen { background: linear-gradient(145deg, #171716, #403b30); color: #f9f4e7; }
.template-phone--modern-cinematic .template-phone__screen { background: radial-gradient(circle at 75% 12%, #40537b, transparent 34%), linear-gradient(145deg, #080b14, #0f1728); color: #f5f0e6; }
.template-phone--dolce-vita .template-phone__screen{background:linear-gradient(#fffdfb,#c4dce6);color:#4a4a4a}
.template-phone--blossom-oud .template-phone__screen{background:linear-gradient(#f9e6d4,#dfc49e);color:#866739}
.template-phone--sacred-garden .template-phone__screen{background:linear-gradient(#f9f0e0,#ded3b8);color:#a67d2b}
</style>
